//! Incremental response parser for the adopted Flash-Next template DATA, ported one to one from `native/src/response.cpp`.
//!
//! It frames `<think>...</think>` and `<tool_call><function=name> <parameter=name>\nVALUE\n</parameter>...</function></tool_call>`. This is NOT a generic XML parser or a JSON tool-envelope dialect. Parameter typing is explicit because raw strings such as `true` cannot be distinguished from JSON booleans in DATA.
//!
//! `initial_thinking` MUST match the renderer's generation prefix: enabled thinking already opens `<think>` before the generated bytes begin. Tool-like content in thinking is inert. Arguments are never streamed as executable records: ALL tool records are withheld until [`ResponseParser::finish`] validates the complete response, all frames and the no-suffix-after-tools rule. A terminal error publishes no tool records. Text/thinking records may remain on error and must not be confused with a successfully completed response.
//!
//! `feed`/`finish` return a sticky explicit status; input after `finish` is an error. Records are coalesced and may be extended by `feed`. No tools are executed. Global call correlation, full JSON-schema semantics, permissions, prompt-injection defenses and API integrity are caller duties.

use std::collections::BTreeSet;
use std::fmt;

use tokspur_json::{
    Json, JsonError, JsonLimits, Kind, UnicodeError, parse_json_limited, unicode_scalars,
};

use crate::cxx::{FromChars, find, find_from, from_chars_f64};

/// `ParameterType`, in the C++ enumerator order.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ParameterType {
    RawString,
    Boolean,
    Number,
    Object,
    Array,
    NullValue,
    JsonValue,
}

/// `ParameterSpec`. `r#type` is the C++ `type` field.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ParameterSpec {
    pub name: Vec<u8>,
    pub r#type: ParameterType,
    pub required: bool,
}

impl ParameterSpec {
    pub fn new(name: impl Into<Vec<u8>>, r#type: ParameterType, required: bool) -> Self {
        Self {
            name: name.into(),
            r#type,
            required,
        }
    }
}

/// `ToolSpec`.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ToolSpec {
    pub name: Vec<u8>,
    pub parameters: Vec<ParameterSpec>,
}

impl ToolSpec {
    pub fn new(name: impl Into<Vec<u8>>, parameters: Vec<ParameterSpec>) -> Self {
        Self {
            name: name.into(),
            parameters,
        }
    }
}

/// `ResponseLimits`, with the C++ defaults.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct ResponseLimits {
    pub bytes: usize,
    pub call_bytes: usize,
    pub records: usize,
    pub calls: usize,
    pub json_nodes: usize,
    pub json_depth: usize,
}

impl Default for ResponseLimits {
    fn default() -> Self {
        Self {
            bytes: 1024 * 1024,
            call_bytes: 64 * 1024,
            records: 4096,
            calls: 128,
            json_nodes: 16384,
            json_depth: 32,
        }
    }
}

/// `ResponseStatus`.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ResponseStatus {
    Incomplete,
    Complete,
    Error,
}

/// `ResponseKind`.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ResponseKind {
    Text,
    Thinking,
    Tool,
}

/// One coalesced record. `ordinal` is response-local only, never a global or model call ID. `Debug` prints sizes only: records carry generated text, reasoning and tool arguments.
#[derive(Clone, PartialEq, Eq)]
pub struct ResponseRecord {
    pub kind: ResponseKind,
    pub text: Vec<u8>,
    pub ordinal: usize,
    pub name: Vec<u8>,
    pub arguments: Json,
}

impl fmt::Debug for ResponseRecord {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        formatter
            .debug_struct("ResponseRecord")
            .field("kind", &self.kind)
            .field("text", &Redacted(self.text.len()))
            .field("ordinal", &self.ordinal)
            .field("name", &Redacted(self.name.len()))
            .field("arguments", &self.arguments)
            .finish()
    }
}

/// Prints `<N bytes>` in place of a byte string.
struct Redacted(usize);

impl fmt::Debug for Redacted {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(formatter, "<{} bytes>", self.0)
    }
}

/// The C++ `FormatError` raised by the parser. `Display` is the exact C++ `what()` text, which [`ResponseParser::error`] records.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ResponseError {
    /// `ResponseParser::new` refused its limits or tool manifest.
    Configure(&'static str),
    /// A tool or parameter name failed the `name` rules.
    Name(&'static str),
    /// A tool or parameter name is not valid UTF-8 (`unicode_scalars`).
    Text(UnicodeError),
    /// `feed` or `finish` refused the bytes or frames.
    Parse(&'static str),
    /// `parse_json` refused a typed parameter value.
    Argument(JsonError),
}

impl fmt::Display for ResponseError {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::Configure(reason) | Self::Name(reason) | Self::Parse(reason) => {
                formatter.write_str(reason)
            }
            Self::Text(error) => error.fmt(formatter),
            Self::Argument(error) => error.fmt(formatter),
        }
    }
}

impl std::error::Error for ResponseError {
    fn source(&self) -> Option<&(dyn std::error::Error + 'static)> {
        match self {
            Self::Text(error) => Some(error),
            Self::Argument(error) => Some(error),
            Self::Configure(_) | Self::Name(_) | Self::Parse(_) => None,
        }
    }
}

fn require(condition: bool, message: &'static str) -> Result<(), ResponseError> {
    if condition {
        Ok(())
    } else {
        Err(ResponseError::Parse(message))
    }
}

fn require_configure(condition: bool, message: &'static str) -> Result<(), ResponseError> {
    if condition {
        Ok(())
    } else {
        Err(ResponseError::Configure(message))
    }
}

fn require_name(condition: bool, message: &'static str) -> Result<(), ResponseError> {
    if condition {
        Ok(())
    } else {
        Err(ResponseError::Name(message))
    }
}

fn space(c: u8) -> bool {
    c == b' ' || c == b'\n' || c == b'\r' || c == b'\t'
}

fn trim(value: &[u8]) -> &[u8] {
    let start = value.iter().position(|&c| !space(c)).unwrap_or(value.len());
    let end = value
        .iter()
        .rposition(|&c| !space(c))
        .map_or(start, |last| last + 1);
    &value[start..end.max(start)]
}

fn name(value: &[u8], function: bool) -> Result<(), ResponseError> {
    require_name(
        !value.is_empty() && value.len() <= if function { 64 } else { 1024 },
        "response name length limit",
    )?;
    unicode_scalars(value).map_err(ResponseError::Text)?;
    for &c in value {
        require_name(
            c >= 32 && c != b'<' && c != b'>' && c != 127,
            "unsafe response name",
        )?;
        if function {
            require_name(
                c.is_ascii_alphanumeric() || c == b'-' || c == b'_' || c == b'.',
                "unsupported response function name",
            )?;
        }
    }
    Ok(())
}

fn finite_numbers(value: &Json) -> Result<(), ResponseError> {
    match value {
        Json::Number(number) => require(
            matches!(from_chars_f64(number.lexeme()), FromChars::Value(parsed) if parsed.is_finite()),
            "unrepresentable response argument number",
        ),
        Json::Array(items) => items.iter().try_for_each(finite_numbers),
        Json::Object(fields) => fields.iter().try_for_each(|(_, item)| finite_numbers(item)),
        Json::Null | Json::Bool(_) | Json::String(_) => Ok(()),
    }
}

const MARKERS: [&[u8]; 9] = [
    b"<think>",
    b"</think>",
    b"<tool_call>",
    b"</tool_call>",
    b"<function=",
    b"</function>",
    b"<parameter=",
    b"</parameter>",
    b"<|im_end|>",
];

const THINKING_MARKERS: [&[u8]; 2] = [b"</think>", b"<|im_end|>"];

/// Markers a parameter value may not contain.
const RESERVED: [&[u8]; 10] = [
    b"<tool_call>",
    b"</tool_call>",
    b"<function=",
    b"<parameter=",
    b"</function>",
    b"</parameter>",
    b"<think>",
    b"</think>",
    b"<|im_end|>",
    b"<|im_start|>",
];

/// `validate_response_parameter_markers` (`native/src/response.cpp`).
pub fn validate_response_parameter_markers(raw: &[u8]) -> Result<(), ResponseError> {
    require(
        RESERVED
            .iter()
            .all(|marker| raw.windows(marker.len()).all(|window| window != *marker)),
        "reserved response marker inside parameter",
    )
}

/// The longest proper prefix of any token that `value` ends with.
fn held_suffix(value: &[u8], tokens: &[&[u8]]) -> usize {
    let mut held = 0;
    for token in tokens {
        for n in (1..token.len()).take_while(|&n| n <= value.len()) {
            if value.ends_with(&token[..n]) {
                held = held.max(n);
            }
        }
    }
    held
}

/// The length of `value` without a trailing incomplete UTF-8 sequence.
fn complete_utf8(value: &[u8]) -> usize {
    if value.is_empty() {
        return 0;
    }
    let mut start = value.len() - 1;
    while start > 0 && value[start] & 0xc0 == 0x80 {
        start -= 1;
    }
    let c = value[start];
    let expected = if c < 128 {
        1
    } else if c < 0xe0 {
        2
    } else if c < 0xf0 {
        3
    } else {
        4
    };
    if value.len() - start < expected {
        start
    } else {
        value.len()
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum Mode {
    Text,
    Thinking,
    Call,
    Ended,
    PossibleCall,
}

#[derive(Clone, Copy)]
struct LiteralState {
    delimiter: u8,
    run: u8,
    width: usize,
    run_width: usize,
    indent: usize,
    fenced: bool,
    line_start: bool,
    run_line: bool,
    fence_close: bool,
    escaped: bool,
    indented: bool,
    quoted_line: bool,
    previous: u8,
}

impl Default for LiteralState {
    fn default() -> Self {
        Self {
            delimiter: 0,
            run: 0,
            width: 0,
            run_width: 0,
            indent: 0,
            fenced: false,
            line_start: true,
            run_line: false,
            fence_close: false,
            escaped: false,
            indented: false,
            quoted_line: false,
            previous: 0,
        }
    }
}

impl LiteralState {
    fn controls(&mut self, c: u8) -> bool {
        if self.run != 0 && c != self.run {
            if self.delimiter == 0 {
                if self.run == b'`' || self.run_line && self.run_width >= 3 {
                    self.delimiter = self.run;
                    self.width = self.run_width;
                    self.fenced = self.run_line && self.run_width >= 3;
                }
            } else if self.delimiter == self.run {
                if self.fenced && self.run_line && self.run_width >= self.width {
                    self.fence_close = true;
                } else if !self.fenced && self.run_width == self.width {
                    self.delimiter = 0;
                }
            }
            self.run = 0;
        }
        self.delimiter == 0
            && !self.escaped
            && !self.indented
            && !self.quoted_line
            && !matches!(self.previous, b'"' | b'\'')
    }

    fn advance(&mut self, c: u8) {
        if self.fence_close && !matches!(c, b' ' | b'\t' | b'\r' | b'\n') {
            self.fence_close = false;
        }
        if self.delimiter == 0 && self.line_start && c == b'>' {
            self.quoted_line = true;
        }
        if !self.escaped
            && !self.indented
            && !self.quoted_line
            && (c == b'`'
                || c == b'~' && (self.line_start || self.delimiter == b'~' || self.run == b'~'))
        {
            if self.run == c {
                self.run_width += 1;
            } else {
                self.run = c;
                self.run_width = 1;
                self.run_line = self.line_start && self.indent <= 3;
            }
        }
        self.escaped = self.delimiter == 0 && c == b'\\' && !self.escaped;
        if matches!(c, b'\n' | b'\r') {
            if self.fence_close {
                self.delimiter = 0;
                self.fence_close = false;
            }
            self.line_start = true;
            self.indent = 0;
            self.indented = false;
            self.quoted_line = false;
        } else if c == b'\t' && self.line_start {
            self.line_start = false;
            self.indent = 4;
            if self.delimiter == 0 {
                self.indented = true;
            }
        } else if c == b' ' && self.line_start {
            self.indent = (self.indent + 1).min(4);
            if self.indent == 4 {
                self.line_start = false;
                if self.delimiter == 0 {
                    self.indented = true;
                }
            }
        } else {
            self.line_start = false;
        }
        self.previous = c;
    }
}

/// `ResponseParser`. `Debug` prints only the status, error text and counts: the pending bytes and records carry generated text and tool arguments.
pub struct ResponseParser {
    tools: Vec<ToolSpec>,
    limits: ResponseLimits,
    mode: Mode,
    status: ResponseStatus,
    pending: Vec<u8>,
    error: String,
    records: Vec<ResponseRecord>,
    calls: Vec<ResponseRecord>,
    received: usize,
    call_search: usize,
    call_in_parameter: bool,
    point: u32,
    minimum: u32,
    remaining: u32,
    thought: bool,
    visible: bool,
    had_calls: bool,
    executor_parameters: bool,
    token_framing: bool,
    literal: LiteralState,
}

impl fmt::Debug for ResponseParser {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        formatter
            .debug_struct("ResponseParser")
            .field("status", &self.status)
            .field("error", &self.error)
            .field("records", &self.records.len())
            .field("bytes_received", &self.received)
            .finish_non_exhaustive()
    }
}

impl ResponseParser {
    /// Validates the limits and the tool manifest.
    pub fn new(
        tools: Vec<ToolSpec>,
        initial_thinking: bool,
        limits: ResponseLimits,
    ) -> Result<Self, ResponseError> {
        Self::new_with_executor_parameters(tools, initial_thinking, limits, false)
    }

    /// Validates the limits and the tool manifest, with optional executor-deferred parameter schema matching.
    pub fn new_with_executor_parameters(
        tools: Vec<ToolSpec>,
        initial_thinking: bool,
        limits: ResponseLimits,
        executor_parameters: bool,
    ) -> Result<Self, ResponseError> {
        require_configure(
            limits.bytes != 0
                && limits.bytes <= 8 * 1024 * 1024
                && limits.call_bytes != 0
                && limits.call_bytes <= limits.bytes
                && limits.records != 0
                && limits.records <= 65536
                && limits.calls != 0
                && limits.calls <= 128
                && limits.json_nodes != 0
                && limits.json_nodes <= 1_000_000
                && limits.json_depth != 0
                && limits.json_depth <= 64,
            "invalid response limits",
        )?;
        require_configure(tools.len() <= 512, "too many response tools")?;
        let mut names = BTreeSet::new();
        let mut schema_bytes = 0usize;
        for tool in &tools {
            name(&tool.name, true)?;
            require_configure(
                names.insert(tool.name.as_slice()) && tool.parameters.len() <= 256,
                "duplicate tool or too many response parameters",
            )?;
            schema_bytes += tool.name.len();
            let mut parameters = BTreeSet::new();
            for parameter in &tool.parameters {
                name(&parameter.name, false)?;
                // The C++ also refuses out-of-range enumerators here; a Rust `ParameterType` cannot hold one.
                require_configure(
                    parameters.insert(parameter.name.as_slice()),
                    "invalid or duplicate response parameter spec",
                )?;
                schema_bytes += parameter.name.len();
                require_configure(schema_bytes <= 1024 * 1024, "response schema byte limit")?;
            }
        }
        Ok(Self {
            tools,
            limits,
            mode: if initial_thinking {
                Mode::Thinking
            } else {
                Mode::Text
            },
            status: ResponseStatus::Incomplete,
            pending: Vec::new(),
            error: String::new(),
            records: Vec::new(),
            calls: Vec::new(),
            received: 0,
            call_search: 0,
            call_in_parameter: false,
            point: 0,
            minimum: 0,
            remaining: 0,
            thought: initial_thinking,
            visible: false,
            had_calls: false,
            executor_parameters,
            token_framing: false,
            literal: LiteralState::default(),
        })
    }

    pub fn status(&self) -> ResponseStatus {
        self.status
    }

    /// Uses token IDs for termination while preserving literal marker spellings in the body.
    pub fn with_token_framing(mut self) -> Self {
        self.token_framing = true;
        self
    }

    /// The recorded error text; empty unless the status is `Error`.
    pub fn error(&self) -> &str {
        &self.error
    }

    pub fn records(&self) -> &[ResponseRecord] {
        &self.records
    }

    pub fn bytes_received(&self) -> usize {
        self.received
    }

    /// Appends generated bytes; the status is sticky once it leaves `Incomplete`.
    pub fn feed(&mut self, bytes: &[u8]) -> ResponseStatus {
        if self.status == ResponseStatus::Error {
            return self.status;
        }
        if self.status == ResponseStatus::Complete {
            self.fail("input after finished response");
            return self.status;
        }
        if let Err(error) = self.accept(bytes) {
            self.fail(&error.to_string());
        }
        self.status
    }

    /// Validates the whole response and only then publishes its tool records.
    pub fn finish(&mut self) -> ResponseStatus {
        if self.status != ResponseStatus::Incomplete {
            return self.status;
        }
        if let Err(error) = self.complete() {
            self.fail(&error.to_string());
        }
        self.status
    }

    /// The body of `feed`'s `try` block.
    fn accept(&mut self, bytes: &[u8]) -> Result<(), ResponseError> {
        require(
            bytes.len() <= self.limits.bytes - self.received,
            "response byte limit",
        )?;
        self.utf8(bytes)?;
        self.received += bytes.len();
        self.pending.extend_from_slice(bytes);
        self.process(false)
    }

    /// The body of `finish`'s `try` block.
    fn complete(&mut self) -> Result<(), ResponseError> {
        require(self.remaining == 0, "truncated response UTF-8")?;
        // A reserved-marker prefix at end is truncation, not visible content.
        if !self.token_framing {
            require(
                held_suffix(&self.pending, &MARKERS) == 0,
                "truncated response marker",
            )?;
        }
        self.process(true)?;
        let calls = std::mem::take(&mut self.calls);
        self.records.extend(calls);
        self.status = ResponseStatus::Complete;
        Ok(())
    }

    fn fail(&mut self, message: &str) {
        self.status = ResponseStatus::Error;
        message.clone_into(&mut self.error);
        self.calls.clear();
        self.records
            .retain(|record| record.kind != ResponseKind::Tool);
    }

    fn utf8(&mut self, bytes: &[u8]) -> Result<(), ResponseError> {
        for &c in bytes {
            if self.remaining != 0 {
                require(c & 0xc0 == 0x80, "invalid response UTF-8 continuation")?;
                self.point = (self.point << 6) | u32::from(c & 63);
                self.remaining -= 1;
                if self.remaining == 0 {
                    require(
                        self.point >= self.minimum
                            && self.point <= 0x10ffff
                            && !(0xd800..=0xdfff).contains(&self.point),
                        "invalid response Unicode scalar",
                    )?;
                }
            } else if c >= 128 {
                require((0xc2..=0xf4).contains(&c), "invalid response UTF-8 lead")?;
                self.remaining = if c < 0xe0 {
                    1
                } else if c < 0xf0 {
                    2
                } else {
                    3
                };
                self.minimum = match self.remaining {
                    1 => 0x80,
                    2 => 0x800,
                    _ => 0x10000,
                };
                self.point = u32::from(c) & ((1u32 << (6 - self.remaining)) - 1);
            } else {
                require(c != 0, "NUL byte in response")?;
            }
        }
        Ok(())
    }

    fn emit(&mut self, kind: ResponseKind, value: &[u8]) -> Result<(), ResponseError> {
        if value.is_empty() {
            return Ok(());
        }
        if kind == ResponseKind::Text && !trim(value).is_empty() {
            self.visible = true;
        }
        match self.records.last_mut() {
            Some(last) if last.kind == kind => last.text.extend_from_slice(value),
            _ => {
                require(
                    self.records.len() + self.calls.len() < self.limits.records,
                    "response record limit",
                )?;
                self.records.push(ResponseRecord {
                    kind,
                    text: value.to_vec(),
                    ordinal: 0,
                    name: Vec::new(),
                    arguments: Json::Null,
                });
            }
        }
        Ok(())
    }

    fn parse_call(&mut self, body: &[u8]) -> Result<(), ResponseError> {
        require(
            self.calls.len() < self.limits.calls,
            "response call count limit",
        )?;
        let mut body = trim(body);
        require(
            body.starts_with(b"<function="),
            "response call lacks function frame",
        )?;
        body = &body[10..];
        let Some(close) = body.iter().position(|&c| c == b'>') else {
            return Err(ResponseError::Parse("response function name is incomplete"));
        };
        let function_name = &body[..close];
        name(function_name, true)?;
        let Some(tool) = self.tools.iter().find(|item| item.name == function_name) else {
            return Err(ResponseError::Parse("unknown response tool"));
        };
        body = &body[close + 1..];
        let mut arguments = tokspur_json::Object::new();
        let mut seen = BTreeSet::new();
        loop {
            body = trim(body);
            if let Some(rest) = body.strip_prefix(b"</function>") {
                require(trim(rest).is_empty(), "data after response function frame")?;
                break;
            }
            require(
                body.starts_with(b"<parameter="),
                "invalid response parameter frame",
            )?;
            body = &body[11..];
            let Some(end) = body.iter().position(|&c| c == b'>') else {
                return Err(ResponseError::Parse("incomplete response parameter name"));
            };
            let key = &body[..end];
            name(key, false)?;
            require(seen.insert(key), "duplicate response parameter")?;
            let spec = tool.parameters.iter().find(|item| item.name == key);
            if !self.executor_parameters && spec.is_none() {
                return Err(ResponseError::Parse("unknown response parameter"));
            }
            body = &body[end + 1..];
            require(
                body.starts_with(b"\n"),
                "response parameter lacks template newline",
            )?;
            body = &body[1..];
            let Some(stop) = find(body, b"\n</parameter>") else {
                return Err(ResponseError::Parse("incomplete response parameter value"));
            };
            let framed = &body[..stop];
            if !self.token_framing {
                validate_response_parameter_markers(framed)?;
            }
            let raw = framed;
            let value = match spec {
                Some(spec) if spec.r#type == ParameterType::RawString => Json::String(raw.to_vec()),
                Some(spec) if spec.r#type == ParameterType::JsonValue => {
                    match parse_json_limited(
                        trim(raw),
                        JsonLimits::new(
                            self.limits.call_bytes,
                            self.limits.json_nodes,
                            self.limits.json_depth,
                        ),
                    ) {
                        Ok(value) => {
                            finite_numbers(&value)?;
                            value
                        }
                        Err(_) => Json::String(raw.to_vec()),
                    }
                }
                Some(spec) if !self.executor_parameters => {
                    let limits = JsonLimits::new(
                        self.limits.call_bytes,
                        self.limits.json_nodes,
                        self.limits.json_depth,
                    );
                    let value =
                        parse_json_limited(trim(raw), limits).map_err(ResponseError::Argument)?;
                    let expected = match spec.r#type {
                        ParameterType::Boolean => Kind::Boolean,
                        ParameterType::Number => Kind::Number,
                        ParameterType::Object => Kind::Object,
                        ParameterType::Array => Kind::Array,
                        ParameterType::NullValue
                        | ParameterType::RawString
                        | ParameterType::JsonValue => Kind::Null,
                    };
                    require(
                        value.kind() == expected,
                        "wrong response parameter JSON type",
                    )?;
                    finite_numbers(&value)?;
                    value
                }
                spec => {
                    let limits = JsonLimits::new(
                        self.limits.call_bytes,
                        self.limits.json_nodes,
                        self.limits.json_depth,
                    );
                    let expected = spec.map(|item| match item.r#type {
                        ParameterType::Boolean => Kind::Boolean,
                        ParameterType::Number => Kind::Number,
                        ParameterType::Object => Kind::Object,
                        ParameterType::Array => Kind::Array,
                        ParameterType::NullValue
                        | ParameterType::RawString
                        | ParameterType::JsonValue => Kind::Null,
                    });
                    match parse_json_limited(trim(raw), limits) {
                        Ok(candidate)
                            if finite_numbers(&candidate).is_ok()
                                && expected.is_none_or(|kind| candidate.kind() == kind) =>
                        {
                            candidate
                        }
                        _ => Json::String(raw.to_vec()),
                    }
                }
            };
            arguments.push((key.to_vec(), value));
            body = &body[stop + 13..];
        }
        if !self.executor_parameters {
            for parameter in &tool.parameters {
                require(
                    !parameter.required || seen.contains(parameter.name.as_slice()),
                    "missing required response parameter",
                )?;
            }
        }
        require(
            self.records.len() + self.calls.len() < self.limits.records,
            "response record limit",
        )?;
        self.calls.push(ResponseRecord {
            kind: ResponseKind::Tool,
            text: Vec::new(),
            ordinal: self.calls.len(),
            name: function_name.to_vec(),
            arguments: Json::Object(arguments),
        });
        Ok(())
    }

    fn token_framed_call_end(&mut self) -> Result<Option<usize>, ResponseError> {
        loop {
            if self.call_in_parameter {
                let Some(end) = find_from(&self.pending, b"\n</parameter>", self.call_search)
                else {
                    self.call_search = self.call_search.max(self.pending.len().saturating_sub(12));
                    return Ok(None);
                };
                self.call_search = end + 13;
                self.call_in_parameter = false;
            } else {
                let parameter = find_from(&self.pending, b"<parameter=", self.call_search);
                let end = find_from(&self.pending, b"</tool_call>", self.call_search);
                if let Some(end) = end
                    && parameter.is_none_or(|parameter| end < parameter)
                {
                    return Ok(Some(end));
                }
                let Some(parameter) = parameter else {
                    self.call_search = self.call_search.max(self.pending.len().saturating_sub(11));
                    return Ok(None);
                };
                let Some(name_end) = self.pending[parameter + 11..]
                    .iter()
                    .position(|&c| c == b'>')
                else {
                    require_name(
                        self.pending.len() - parameter <= 11 + 1024,
                        "response name length limit",
                    )?;
                    self.call_search = parameter;
                    return Ok(None);
                };
                self.call_search = parameter + 11 + name_end + 1;
                self.call_in_parameter = true;
            }
        }
    }

    fn process_token_framed(&mut self, final_input: bool) -> Result<(), ResponseError> {
        while !self.pending.is_empty() || self.mode == Mode::PossibleCall {
            if self.mode == Mode::PossibleCall {
                require(
                    self.pending.len() <= self.limits.call_bytes,
                    "response call byte limit",
                )?;
                while self.call_search < self.pending.len()
                    && matches!(self.pending[self.call_search], b' ' | b'\t' | b'\r' | b'\n')
                {
                    self.call_search += 1;
                }
                let rest = &self.pending[self.call_search..];
                if rest.starts_with(b"<function=") {
                    self.mode = Mode::Call;
                    self.call_search = 0;
                    self.call_in_parameter = false;
                    continue;
                }
                if !final_input && b"<function=".starts_with(rest) {
                    return Ok(());
                }
                require(
                    rest.is_empty() || !b"<function=".starts_with(rest),
                    "truncated response tool call",
                )?;
                require(!self.had_calls, "text after response tool calls")?;
                self.emit(ResponseKind::Text, b"<tool_call>")?;
                self.mode = Mode::Text;
                self.call_search = 0;
                self.call_in_parameter = false;
                continue;
            }
            if self.mode == Mode::Call {
                let end = self.token_framed_call_end()?;
                require(
                    self.pending.len() <= self.limits.call_bytes
                        || end.is_some_and(|end| end <= self.limits.call_bytes),
                    "response call byte limit",
                )?;
                let Some(end) = end else {
                    require(!final_input, "truncated response tool call")?;
                    return Ok(());
                };
                let frame: Vec<u8> = self.pending.drain(..end + 12).collect();
                self.parse_call(&frame[..end])?;
                self.mode = Mode::Text;
                self.had_calls = true;
                self.call_search = 0;
                self.call_in_parameter = false;
                self.literal = LiteralState::default();
                continue;
            }
            let mut state = self.literal;
            let mut visible = self.visible;
            let mut position = self.pending.len();
            let mut token: &[u8] = b"";
            let mut held = false;
            for (i, &c) in self.pending.iter().enumerate() {
                if state.controls(c) {
                    let candidates: &[&[u8]] = if self.mode == Mode::Thinking {
                        &[b"</think>"]
                    } else if !self.thought && !visible && !self.had_calls {
                        &[b"<think>", b"<tool_call>"]
                    } else {
                        &[b"<tool_call>"]
                    };
                    for &candidate in candidates {
                        if candidate == b"<tool_call>" && self.tools.is_empty() {
                            continue;
                        }
                        let rest = &self.pending[i..];
                        if rest.starts_with(candidate) {
                            position = i;
                            token = candidate;
                            break;
                        }
                        if !final_input && candidate.starts_with(rest) {
                            position = i;
                            held = true;
                            break;
                        }
                    }
                    if position != self.pending.len() {
                        break;
                    }
                }
                state.advance(c);
                if self.mode == Mode::Text && !matches!(c, b' ' | b'\t' | b'\r' | b'\n') {
                    visible = true;
                }
            }
            let safe = complete_utf8(&self.pending[..position]);
            let text: Vec<u8> = self.pending.drain(..safe).collect();
            for &c in &text {
                self.literal.controls(c);
                self.literal.advance(c);
            }
            if self.had_calls {
                require(trim(&text).is_empty(), "text after response tool calls")?;
            } else {
                self.emit(
                    if self.mode == Mode::Thinking {
                        ResponseKind::Thinking
                    } else {
                        ResponseKind::Text
                    },
                    &text,
                )?;
            }
            if token.is_empty() || held || safe != position {
                break;
            }
            self.pending.drain(..token.len());
            self.literal = LiteralState::default();
            if token == b"</think>" {
                self.mode = Mode::Text;
            } else if token == b"<think>" {
                self.mode = Mode::Thinking;
                self.thought = true;
            } else {
                self.mode = Mode::PossibleCall;
                self.call_search = 0;
                self.call_in_parameter = false;
            }
        }
        if final_input {
            require(
                self.mode != Mode::Call && self.mode != Mode::Thinking,
                "truncated response control frame",
            )?;
        }
        Ok(())
    }

    fn process(&mut self, r#final: bool) -> Result<(), ResponseError> {
        if self.token_framing {
            return self.process_token_framed(r#final);
        }
        while !self.pending.is_empty() {
            if self.mode == Mode::Ended {
                require(
                    trim(&self.pending).is_empty(),
                    "data after response terminal marker",
                )?;
                self.pending.clear();
                return Ok(());
            }
            if self.mode == Mode::Call {
                let end = find_from(&self.pending, b"</tool_call>", self.call_search);
                require(
                    self.pending.len() <= self.limits.call_bytes
                        || end.is_some_and(|end| end <= self.limits.call_bytes),
                    "response call byte limit",
                )?;
                let Some(end) = end else {
                    self.call_search = self.pending.len().saturating_sub(11);
                    require(!r#final, "truncated response tool call")?;
                    return Ok(());
                };
                // The C++ erases the frame after parsing it; once parsing fails the status is sticky and the pending bytes are never read again.
                let frame: Vec<u8> = self.pending.drain(..end + 12).collect();
                self.parse_call(&frame[..end])?;
                self.mode = Mode::Text;
                self.had_calls = true;
                self.call_search = 0;
                continue;
            }
            let active: &[&[u8]] = if self.mode == Mode::Thinking {
                &THINKING_MARKERS
            } else {
                &MARKERS
            };
            let mut position = None;
            let mut token: &[u8] = b"";
            for &candidate in active {
                if let Some(found) = find(&self.pending, candidate)
                    && position.is_none_or(|position| found < position)
                {
                    position = Some(found);
                    token = candidate;
                }
            }
            let size = match position {
                Some(position) => position,
                None if r#final => self.pending.len(),
                None => self.pending.len() - held_suffix(&self.pending, active),
            };
            let safe = complete_utf8(&self.pending[..size]);
            let chunk: Vec<u8> = self.pending.drain(..safe).collect();
            if self.had_calls {
                require(trim(&chunk).is_empty(), "text after response tool calls")?;
            } else {
                let kind = if self.mode == Mode::Thinking {
                    ResponseKind::Thinking
                } else {
                    ResponseKind::Text
                };
                self.emit(kind, &chunk)?;
            }
            if position.is_none() || safe != size {
                if r#final {
                    require(
                        self.pending.is_empty(),
                        "truncated response marker or UTF-8",
                    )?;
                }
                return Ok(());
            }
            self.pending.drain(..token.len());
            match token {
                b"</think>" => {
                    require(
                        self.mode == Mode::Thinking,
                        "unexpected response thinking close",
                    )?;
                    self.mode = Mode::Text;
                }
                b"<think>" => {
                    require(
                        self.mode == Mode::Text
                            && !self.thought
                            && !self.visible
                            && !self.had_calls,
                        "unexpected response thinking open",
                    )?;
                    self.thought = true;
                    self.mode = Mode::Thinking;
                }
                b"<tool_call>" => self.mode = Mode::Call,
                b"<|im_end|>" => {
                    require(
                        self.mode != Mode::Thinking,
                        "terminal marker inside thinking",
                    )?;
                    self.mode = Mode::Ended;
                }
                _ => return Err(ResponseError::Parse("unexpected response control marker")),
            }
        }
        if r#final {
            require(
                self.mode != Mode::Call && self.mode != Mode::Thinking,
                "truncated response control frame",
            )?;
        }
        Ok(())
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn ping() -> Vec<ToolSpec> {
        vec![ToolSpec::new(
            "ping",
            vec![ParameterSpec::new(
                "secret",
                ParameterType::RawString,
                false,
            )],
        )]
    }

    fn parser(thinking: bool) -> ResponseParser {
        ResponseParser::new(ping(), thinking, ResponseLimits::default()).unwrap()
    }

    #[test]
    fn debug_redacts_text_reasoning_and_arguments() {
        let mut parser = parser(true);
        let first = b"hidden plan</think>visible answer<tool_call><function=ping>";
        let second = b"<parameter=secret>\ntoken 151644\n</parameter></function></tool_call>";
        parser.feed(first);
        parser.feed(second);
        assert_eq!(parser.finish(), ResponseStatus::Complete);
        assert_eq!(
            format!("{parser:?}"),
            format!(
                "ResponseParser {{ status: Complete, error: \"\", records: 3, bytes_received: {}, .. }}",
                first.len() + second.len()
            )
        );
        let printed: Vec<String> = parser
            .records()
            .iter()
            .map(|record| format!("{record:?}"))
            .collect();
        assert_eq!(
            printed,
            [
                "ResponseRecord { kind: Thinking, text: <11 bytes>, ordinal: 0, name: <0 bytes>, arguments: Json::Null }",
                "ResponseRecord { kind: Text, text: <14 bytes>, ordinal: 0, name: <0 bytes>, arguments: Json::Null }",
                "ResponseRecord { kind: Tool, text: <0 bytes>, ordinal: 0, name: <4 bytes>, arguments: Json::Object(1 fields) }",
            ]
        );
        let everything = format!("{parser:#?} {:#?}", parser.records());
        for secret in ["hidden", "visible", "151644", "ping"] {
            assert!(!everything.contains(secret), "{secret}");
        }
    }

    #[test]
    fn errors_display_the_exact_cpp_messages_and_stay_transparent() {
        use std::error::Error;
        let cases = [
            (
                ResponseError::Configure("invalid response limits"),
                "invalid response limits",
                false,
            ),
            (
                ResponseError::Name("unsafe response name"),
                "unsafe response name",
                false,
            ),
            (
                ResponseError::Text(UnicodeError::Decode("invalid UTF-8 input")),
                "invalid UTF-8 input",
                true,
            ),
            (
                ResponseError::Parse("response byte limit"),
                "response byte limit",
                false,
            ),
            (
                ResponseError::Argument(JsonError::Parse("trailing JSON data")),
                "trailing JSON data",
                true,
            ),
        ];
        for (error, message, has_source) in cases {
            assert_eq!(error.to_string(), message);
            assert_eq!(error.source().is_some(), has_source);
        }
    }

    #[test]
    fn parameter_markers_reject_all_reserved_delimiters() {
        assert!(validate_response_parameter_markers(b"plain value").is_ok());
        for marker in RESERVED {
            let mut payload = b"before ".to_vec();
            payload.extend_from_slice(marker);
            payload.extend_from_slice(b" after");
            assert_eq!(
                validate_response_parameter_markers(&payload)
                    .unwrap_err()
                    .to_string(),
                "reserved response marker inside parameter"
            );
        }
    }

    #[test]
    fn trim_strips_only_ascii_template_whitespace() {
        assert_eq!(trim(b" \t\r\nx y\n "), b"x y");
        assert_eq!(trim(b" \n\t\r"), b"");
        assert_eq!(trim(b""), b"");
        assert_eq!(
            trim("\u{a0}x\u{3000}".as_bytes()),
            "\u{a0}x\u{3000}".as_bytes()
        );
    }

    #[test]
    fn held_suffix_keeps_the_longest_marker_prefix() {
        assert_eq!(held_suffix(b"text <tool_ca", &MARKERS), 8);
        assert_eq!(held_suffix(b"text <", &MARKERS), 1);
        assert_eq!(held_suffix(b"text </", &MARKERS), 2);
        assert_eq!(held_suffix(b"<|im_end|", &MARKERS), 9);
        // A whole marker is not held: the search finds it instead.
        assert_eq!(held_suffix(b"<think>", &MARKERS), 0);
        assert_eq!(held_suffix(b"<tool", &MARKERS), 5);
        assert_eq!(held_suffix(b"<tool", &THINKING_MARKERS), 0);
        assert_eq!(held_suffix(b"text <", &THINKING_MARKERS), 1);
        assert_eq!(held_suffix(b"", &MARKERS), 0);
    }

    #[test]
    fn complete_utf8_withholds_only_a_trailing_partial_sequence() {
        assert_eq!(complete_utf8(b""), 0);
        assert_eq!(complete_utf8(b"ab"), 2);
        assert_eq!(complete_utf8("é".as_bytes()), 2);
        assert_eq!(complete_utf8(b"a\xc3"), 1);
        assert_eq!(complete_utf8(b"a\xe6\x97"), 1);
        assert_eq!(complete_utf8(b"a\xf0\x9f\x99"), 1);
        assert_eq!(complete_utf8("🙂".as_bytes()), 4);
    }

    #[test]
    fn input_after_completion_fails_and_withdraws_published_calls() {
        let mut parser = parser(false);
        parser.feed(b"ok<tool_call><function=ping></function></tool_call>");
        assert_eq!(parser.finish(), ResponseStatus::Complete);
        assert_eq!(parser.records().len(), 2);
        // Even an empty feed after finish is refused, and tool records go.
        assert_eq!(parser.feed(b""), ResponseStatus::Error);
        assert_eq!(parser.error(), "input after finished response");
        assert_eq!(parser.records().len(), 1);
        assert_eq!(parser.records()[0].kind, ResponseKind::Text);
        assert_eq!(parser.finish(), ResponseStatus::Error);
        assert_eq!(parser.bytes_received(), 51);
    }

    #[test]
    fn records_coalesce_across_feeds_and_hold_partial_markers() {
        let mut parser = parser(false);
        for chunk in [b"he".as_slice(), b"llo <", b"thi"] {
            assert_eq!(parser.feed(chunk), ResponseStatus::Incomplete);
        }
        // "<thi" is held, not emitted, until the marker resolves.
        assert_eq!(parser.records().len(), 1);
        assert_eq!(parser.records()[0].text, b"hello ");
        // `<think>` after visible text is refused; the status is then sticky.
        assert_eq!(parser.feed(b"nk> "), ResponseStatus::Error);
        assert_eq!(parser.error(), "unexpected response thinking open");
        assert_eq!(parser.feed(b"world"), ResponseStatus::Error);
        assert_eq!(parser.records()[0].text, b"hello ");
    }

    #[test]
    fn utf8_is_validated_across_feed_boundaries() {
        let mut parser = parser(false);
        assert_eq!(parser.feed(b"\xe6"), ResponseStatus::Incomplete);
        assert_eq!(parser.feed(b"\x97"), ResponseStatus::Incomplete);
        assert!(parser.records().is_empty());
        assert_eq!(parser.feed(b"\xa5"), ResponseStatus::Incomplete);
        assert_eq!(parser.records()[0].text, "日".as_bytes());
        assert_eq!(parser.feed(b"\xe0\x9f"), ResponseStatus::Incomplete);
        assert_eq!(parser.feed(b"\xbf"), ResponseStatus::Error);
        assert_eq!(parser.error(), "invalid response Unicode scalar");
    }
}
